import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"困","description":"周易正义 - 困","frontmatter":{"title":"困","description":"周易正义 - 困"},"headers":[],"relativePath":"zh/classics/zhengyi/047.md","filePath":"zh/classics/zhengyi/047.md"}'),l={name:"zh/classics/zhengyi/047.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>泽水困</p></blockquote><blockquote><p>卦辞：亨，贞大人吉，无咎，有言不信。</p></blockquote><blockquote><p>彖曰：困，刚揜也。险以说，困而不失其所亨，其唯君子乎！贞大人吉，以刚中也。有言不信，尚口乃穷也。</p></blockquote><h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><p>王弼：困必通也。处穷而不能自通者，小人也。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“困”者，穷厄委顿之名，道穷力竭，不能自济，故名为“困”。亨者，卦德也。小人遭困，则“穷斯滥矣”。君子遇之，则不改其操。君子处困而不失，其自通之道，故曰“困，亨”也。</p><h3 id="贞-大人吉-无咎。-​" tabindex="-1">贞，大人吉，无咎。 ​ <a class="header-anchor" href="#贞-大人吉-无咎。-​" aria-label="Permalink to “贞，大人吉，无咎。 ​”">​</a></h3><p>王弼：处困而得“无咎”，吉乃免也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：处困而能自通，必是履正体大之人，能济於困，然后得吉而“无咎”，故曰：“贞，大人吉，无咎”也。</p><h3 id="有言不信。-​" tabindex="-1">有言不信。 ​ <a class="header-anchor" href="#有言不信。-​" aria-label="Permalink to “有言不信。 ​”">​</a></h3><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：处困求济，在於正身脩德。若巧言能辞，人所不信，则其道弥穷，故诫之以“有言不信”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="困-刚揜也。-​" tabindex="-1">困，刚揜也。 ​ <a class="header-anchor" href="#困-刚揜也。-​" aria-label="Permalink to “困，刚揜也。 ​”">​</a></h3><p>王弼：刚则揜於柔也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此就二体以释卦名，兑阴卦为柔，坎阳卦为刚，坎在兑下，是“刚见揜於柔也”。刚应升进，今被柔揜，施之於人，其犹君子为小人所蔽以为困穷矣。</p><h3 id="险以说-困而不失其所亨。-​" tabindex="-1">险以说，困而不失其所亨。 ​ <a class="header-anchor" href="#险以说-困而不失其所亨。-​" aria-label="Permalink to “险以说，困而不失其所亨。 ​”">​</a></h3><p>王弼：处险而不改其说，“困而不失其所亨”也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此又就二体名训以释亨德也。坎险而兑说，所以困而能亨者，良由君子遇困，安其所遇，虽居险困之世，不失畅说之心，故曰“险以说，困而不失其所亨”也。</p><h3 id="其唯君子乎-贞-大人吉-以刚中也。-​" tabindex="-1">其唯君子乎？贞，大人吉，以刚中也。 ​ <a class="header-anchor" href="#其唯君子乎-贞-大人吉-以刚中也。-​" aria-label="Permalink to “其唯君子乎？贞，大人吉，以刚中也。 ​”">​</a></h3><p>王弼：处困而用刚，不失其中，履正而能体大者也。能正而不能大博，未能说困者也，故曰“贞，大人吉”也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“其唯君子乎”者，结叹处困能通，非小人之事，唯君子能然也。“贞，大人吉，以刚中”者，此就二五之爻，释“贞，大人”之义。刚则正直，所以为贞，中而不偏，所以能大。若正而不大，未能济困，处困能济，济乃得吉而无咎也，故曰“贞，大人吉，以刚中”也。</p><h3 id="有言不信-尚口乃穷也。-​" tabindex="-1">有言不信，尚口乃穷也。 ​ <a class="header-anchor" href="#有言不信-尚口乃穷也。-​" aria-label="Permalink to “有言不信，尚口乃穷也。 ​”">​</a></h3><p>王弼：处困而言，不见信之时也。非行言之时，而欲用言以免，必穷宅也。其吉在於“贞、大人”，口何为乎？</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：处困求通，在於修德非用言以免困。徒尚口说，更致困穷，故曰“尚口乃穷”也。</p><h2 id="《象》曰-泽无水-困。君子以致命遂志。-​" tabindex="-1">《象》曰：泽无水，困。君子以致命遂志。 ​ <a class="header-anchor" href="#《象》曰-泽无水-困。君子以致命遂志。-​" aria-label="Permalink to “《象》曰：泽无水，困。君子以致命遂志。 ​”">​</a></h2><p>王弼：泽无水，则水在泽下，水在泽下，困之象也。处困而屈其志者，小人也。“君子固穷”，道可忘乎？</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“泽无水，困”者，谓水在泽下，则泽上枯槁，万物皆困，故曰“泽无水困”也。“君子以致命遂志”者，君子之人，守道而死，虽遭困厄之世，期於致命丧身，必当遂其高志，不屈挠而移改也，故曰“致命遂志”也。</p><h2 id="初六-臀困于株木-入于幽谷-三岁不觌。-​" tabindex="-1">初六：臀困于株木，入于幽谷，三岁不觌。 ​ <a class="header-anchor" href="#初六-臀困于株木-入于幽谷-三岁不觌。-​" aria-label="Permalink to “初六：臀困于株木，入于幽谷，三岁不觌。 ​”">​</a></h2><p>王弼：最处底下，沈滞卑困，居无所安，故曰“臀困于株木”也。欲之其应，二隔其路，居则困于株木，进不获拯，必隐遯者也，故曰：“入于幽谷”也。困之为道，不过数岁者也。以困而藏，困解乃出，故曰“三岁不觌”也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“初六臀困于株”至“三岁不觌”。○正义曰：“臀困于株木”者，初六处困之时，以阴爻最居穷下，沈滞卑困，居不获安，若臀之困于株木，故曰“臀困於株木”也。“入于幽谷”者，有应在四，而二隔之，居则困株，进不获拯，势必隐遯者也，故曰“入于幽谷也”。“三岁不觌”者，困之为道，不过数岁，困穷乃出，故曰“三岁不觌”也。</p><h3 id="《象》曰-入于幽谷-幽不明也。-​" tabindex="-1">《象》曰：“入于幽谷”，幽不明也。 ​ <a class="header-anchor" href="#《象》曰-入于幽谷-幽不明也。-​" aria-label="Permalink to “《象》曰：“入于幽谷”，幽不明也。 ​”">​</a></h3><p>王弼：言幽者，不明之辞也。入于不明，以自藏也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“幽不明”者，《象》辞惟释幽字，言幽者，正是不明之辞，所以入不明，以自藏而避困也。释株者，初不谓之株也。</p><h2 id="九二-困于酒食-朱绂方来-利用享祀。征凶-无咎。-​" tabindex="-1">九二：困于酒食，朱绂方来，利用享祀。征凶，无咎。 ​ <a class="header-anchor" href="#九二-困于酒食-朱绂方来-利用享祀。征凶-无咎。-​" aria-label="Permalink to “九二：困于酒食，朱绂方来，利用享祀。征凶，无咎。 ​”">​</a></h2><p>王弼：以阳居阴，尚谦者也。居困之时，处得其中。体夫刚质，而用中履谦，应不在一，心无所私，盛莫先焉。夫谦以待物，物之所归；刚以处险，难之所济。履中则不失其宜，无应则心无私恃，以斯处困，物莫不至，不胜丰衍，故曰“困于酒食”，美之至矣。坎，北方之卦也。朱绂，南方之物也。处困以斯，能招异方者也，故曰“朱绂方来”也。丰衍盈盛，故“利用享祀”。盈而又进，倾之道也。以此而征，凶谁咎乎？故曰“征凶无咎”。</p><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>“九二困于酒食”至“无咎”。○正义曰：“困于酒食”者，九二体刚居阴，处中无应。体刚则健，能济险也。居阴则谦，物所归也。处中则不失其宜，无应则心无私党。处困以斯，物莫不至，不胜丰衍，故曰“困于酒食”也。“朱绂方来，利用享祀”者，绂，祭服也。坎，北方之卦也。绂，南方之物。处困用谦，能招异方者也。故曰“朱绂方来”也。举异方者，明物无不至，酒食丰盈，异方归向，祭则受福，故曰“利用享祀”。“征凶无咎”者，盈而又进，倾败之道，以征必凶，故曰“征凶”。自进致凶，无所怨咎，故曰“无咎”也。</p><h3 id="《象》曰-困于酒食-中有庆也。-​" tabindex="-1">《象》曰：“困于酒食”，中有庆也。 ​ <a class="header-anchor" href="#《象》曰-困于酒食-中有庆也。-​" aria-label="Permalink to “《象》曰：“困于酒食”，中有庆也。 ​”">​</a></h3><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“中有庆”者，言二以中德被物，物之所赖，故曰“有庆”也。</p><h2 id="六三-困于石-据于蒺藜-入于其宫-不见其妻-凶。-​" tabindex="-1">六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。 ​ <a class="header-anchor" href="#六三-困于石-据于蒺藜-入于其宫-不见其妻-凶。-​" aria-label="Permalink to “六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。 ​”">​</a></h2><p>王弼：石之为物，坚而不纳者也，谓四也。三以阴居阳，志武者也。四自纳初，不受已者。二非所据，刚非所乘。上比困石，下据蒺藜，无应而入，焉得配偶？在困处斯，凶其宜也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>“六三困于石”至“不见其妻凶”。○正义曰：“困于石，据于蒺藜”者，石之为物，坚刚而不可入也。蒺藜之草，有剌而不可践也。六三以阴居阳，志怀刚武，己又无应，欲上附於四，四自纳於初，不受己者也，故曰“困于石”也。下欲比二，二又刚阳，非己所据，故曰“据于蒺藜”也。“入于其宫，不见其妻凶”者，无应而入，难得配偶，譬於入宫，不见其妻，处困以斯，凶其宜也，故曰“入于其宫，不见其妻，凶”也。</p><h3 id="《象》曰-据于蒺藜-乘刚也。-入于其宫-不见其妻-不祥也。-​" tabindex="-1">《象》曰：“据于蒺藜”，乘刚也。“入于其宫，不见其妻”，不祥也。 ​ <a class="header-anchor" href="#《象》曰-据于蒺藜-乘刚也。-入于其宫-不见其妻-不祥也。-​" aria-label="Permalink to “《象》曰：“据于蒺藜”，乘刚也。“入于其宫，不见其妻”，不祥也。 ​”">​</a></h3><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“乘刚”者，明二为蒺藜也。“不祥也”者，祥，善也、吉也。不吉，必有凶也。</p><h2 id="九四-来徐徐-困于金车。吝-有终。-​" tabindex="-1">九四：来徐徐，困于金车。吝，有终。 ​ <a class="header-anchor" href="#九四-来徐徐-困于金车。吝-有终。-​" aria-label="Permalink to “九四：来徐徐，困于金车。吝，有终。 ​”">​</a></h2><p>王弼：“金车”，谓二也。二刚以载者也，故谓之金车。“徐徐”者，疑惧之辞也。志在於初而隔於二，履不当位，威令不行。弃之则不能，欲往则畏二，故曰“来徐徐，困于金车”也。有应而不能济之，故曰“吝”也。然以阳居阴，履谦之道，量力而处，不与二争，虽不当位，物终与之，故曰“有终”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>“九四来徐徐”至“有终”。○正义曰：何氏云：“九二以刚德胜，故曰‘金车’也。”“徐徐”者，疑惧之辞。九四有应於初而碍於九二，故曰“困于金车”。欲弃之，惜其配偶疑惧，而行不敢疾速，故“来徐徐”也。有应而不敢往，可耻可恨，故曰“吝”也。以阳居阴，不失谦道，为物之所与，故曰“有终”也。</p><h3 id="《象》曰-来徐徐-志在下也。下谓初也。虽不当位-有与也。-​" tabindex="-1">《象》曰：“来徐徐”，志在下也。下谓初也。虽不当位，有与也。 ​ <a class="header-anchor" href="#《象》曰-来徐徐-志在下也。下谓初也。虽不当位-有与也。-​" aria-label="Permalink to “《象》曰：“来徐徐”，志在下也。下谓初也。虽不当位，有与也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰“有与”者，位虽不当，执谦之故，物所与也。</p><h2 id="九五-劓刖-困于赤绂-乃徐有说-利用祭祀。-​" tabindex="-1">九五：劓刖，困于赤绂，乃徐有说，利用祭祀。 ​ <a class="header-anchor" href="#九五-劓刖-困于赤绂-乃徐有说-利用祭祀。-​" aria-label="Permalink to “九五：劓刖，困于赤绂，乃徐有说，利用祭祀。 ​”">​</a></h2><p>王弼：以阳居阳，任其壮者也。不能以谦致物，物则不附。忿物不附而用其壮猛，行其威刑，异方愈乖，遐迩愈叛。刑之欲以得，乃益所以失也，故曰“劓刖，困于赤绂”也。二以谦得之，五以刚失之，体在中直，能不遂迷困而徐能用其道者也。致物之功，不在於暴，故曰“徐”也。困而后乃徐，徐则有说矣，故曰“困于赤绂，乃徐有说”也。祭祀，所以受福也。履夫尊位，困而能改，不遂其迷以斯祭，祀必得福焉，故曰“利用祭祀”也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>“九五”至“利用祭祀”。○正义曰：九五以阳居阳，用其刚壮，物不归已。见物不归，而用威刑，行其“劓刖”之事。既行其威刑，则“异方愈乖，遐迩愈叛”。兑为西方之卦，赤绂南方之物，故曰“劓刖，困於赤绂”也。此卦九二为以阳居阴，用其谦退，能招异方之物也。此言九五刚猛，不能感异方之物也。若但用其中正之德，招致於物，不在速暴而徐徐，则物归之而有说矣，故曰“乃徐有说”也。居得尊位，困而能反，不执其迷，用其祭祀，则受福也。</p><h3 id="象曰-劓刖-志未得也。-乃徐有说-以中直也。-利用祭祀-受福也。-​" tabindex="-1">象曰：“劓刖”，志未得也。“乃徐有说”，以中直也。“利用祭祀”，受福也。 ​ <a class="header-anchor" href="#象曰-劓刖-志未得也。-乃徐有说-以中直也。-利用祭祀-受福也。-​" aria-label="Permalink to “象曰：“劓刖”，志未得也。“乃徐有说”，以中直也。“利用祭祀”，受福也。 ​”">​</a></h3><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“志未得也”者，由物不附己，己德未得，故曰“志未得”也。“乃徐有说，以中直也”者，居中得直，不贪不暴，终得其应，乃宽缓修其道德，则得喜说，故云“乃徐有说，以中直也”。“利用祭祀，受福”者，若能不遂迷志，用其中正，则异方所归，祭则受福，故曰“利用祭祀，受福”也。</p><h2 id="上六-困于葛藟-于臲卼-曰动悔、有悔-征吉。-​" tabindex="-1">上六：困于葛藟，于臲卼，曰动悔、有悔，征吉。 ​ <a class="header-anchor" href="#上六-困于葛藟-于臲卼-曰动悔、有悔-征吉。-​" aria-label="Permalink to “上六：困于葛藟，于臲卼，曰动悔、有悔，征吉。 ​”">​</a></h2><p>王弼：居困之极，而乘於刚，下无其应，行则愈绕者也。行则缠绕，居不获安，故曰“困于葛藟于臲卼”也。下句无困，因於上也。处困之极，行无通路，居无所安，困之至也。凡物穷则思变，困则谋通，处至困之地，用谋之时也。“曰”者，思谋之辞也。谋之所行，有隙则获，言将何以通至困乎？“曰动悔”，令生有悔，以征则济矣，故曰“动悔有悔，征吉”也。</p><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>“上六困于葛藟”至“征吉”。○正义曰：葛藟，引蔓缠绕之草，臲卼，动摇不安之辞。上六处困之极，极困者也。而乘於刚，下又无应，行则缠绕，居不得安，故院“困於葛藟於臲卼”也。应亦言“困於臲卼”，“困”因於上，省文也。“凡物穷则思变，困则谋通，处至困之地”，是用谋策之时也。“曰”者，思谋之辞也。谋之所行，有隙则获，言将何以通至困乎？为之谋曰：必须发动其可悔之事，令其有悔可知，然后处困求通，可以行而获吉，故曰“动悔，有悔，征吉”。</p><h3 id="《象》曰-困于葛藟-未当也。-​" tabindex="-1">《象》曰：“困于葛藟”，未当也。 ​ <a class="header-anchor" href="#《象》曰-困于葛藟-未当也。-​" aria-label="Permalink to “《象》曰：“困于葛藟”，未当也。 ​”">​</a></h3><p>王弼：所处未当，故致此困也。</p><h3 id="疏-19" tabindex="-1">疏 <a class="header-anchor" href="#疏-19" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“未当也”者，处於困极，而又乘刚，所处不当，故致此困也。</p><h3 id="动悔-有悔-吉行也。-​" tabindex="-1">“动悔，有悔”，吉行也。 ​ <a class="header-anchor" href="#动悔-有悔-吉行也。-​" aria-label="Permalink to ““动悔，有悔”，吉行也。 ​”">​</a></h3><h3 id="疏-20" tabindex="-1">疏 <a class="header-anchor" href="#疏-20" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“吉行”者，知悔而征，行必获吉也。</p>',82)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
